// ProjectionServiceHandler is an implementation of the ironflow.v1.ProjectionService service.
type ProjectionServiceHandler interface {
	// Registration (SDK → Server)
	RegisterProjection(context.Context, *connect.Request[v1.RegisterProjectionRequest]) (*connect.Response[v1.RegisterProjectionResponse], error)
	UnregisterProjection(context.Context, *connect.Request[v1.UnregisterProjectionRequest]) (*connect.Response[v1.UnregisterProjectionResponse], error)
	// Event polling (SDK projection runner)
	PollProjectionEvents(context.Context, *connect.Request[v1.PollProjectionEventsRequest]) (*connect.Response[v1.PollProjectionEventsResponse], error)
	// Real-time event streaming (SDK projection runner — preferred over polling).
	// When the client sets StreamProjectionEventsRequest.accept_heartbeats, the
	// server emits periodic ProjectionEvent frames with kind = HEARTBEAT to keep
	// proxies/LBs from closing idle connections. Heartbeats carry no payload and
	// should be ignored by clients. Clients that do not opt in receive the
	// legacy (pre-0.19.3) stream with no heartbeat frames.
	StreamProjectionEvents(context.Context, *connect.Request[v1.StreamProjectionEventsRequest], *connect.ServerStream[v1.ProjectionEvent]) error
	// State persistence (managed mode)
	SaveProjectionState(context.Context, *connect.Request[v1.SaveProjectionStateRequest]) (*connect.Response[v1.SaveProjectionStateResponse], error)
	// Cursor advance (external mode)
	AckProjectionEvents(context.Context, *connect.Request[v1.AckProjectionEventsRequest]) (*connect.Response[v1.AckProjectionEventsResponse], error)
	// Query API
	GetProjection(context.Context, *connect.Request[v1.GetProjectionRequest]) (*connect.Response[v1.GetProjectionResponse], error)
	ListProjections(context.Context, *connect.Request[v1.ListProjectionsRequest]) (*connect.Response[v1.ListProjectionsResponse], error)
	GetProjectionStatus(context.Context, *connect.Request[v1.GetProjectionStatusRequest]) (*connect.Response[v1.GetProjectionStatusResponse], error)
	// Rebuild
	RebuildProjection(context.Context, *connect.Request[v1.RebuildProjectionRequest]) (*connect.Response[v1.RebuildProjectionResponse], error)
	GetRebuildJob(context.Context, *connect.Request[v1.GetRebuildJobRequest]) (*connect.Response[v1.GetRebuildJobResponse], error)
	CancelRebuild(context.Context, *connect.Request[v1.CancelRebuildRequest]) (*connect.Response[v1.CancelRebuildResponse], error)
	ReportRebuildProgress(context.Context, *connect.Request[v1.ReportRebuildProgressRequest]) (*connect.Response[v1.ReportRebuildProgressResponse], error)
	// Pause/Resume
	PauseProjection(context.Context, *connect.Request[v1.PauseProjectionRequest]) (*connect.Response[v1.PauseProjectionResponse], error)
	ResumeProjection(context.Context, *connect.Request[v1.ResumeProjectionRequest]) (*connect.Response[v1.ResumeProjectionResponse], error)
	// SQL-defined projections
	CreateSQLProjection(context.Context, *connect.Request[v1.CreateSQLProjectionRequest]) (*connect.Response[v1.CreateSQLProjectionResponse], error)
	QuerySQLProjection(context.Context, *connect.Request[v1.QuerySQLProjectionRequest]) (*connect.Response[v1.QuerySQLProjectionResponse], error)
	// Wait for catchup (issue #473) — read-your-writes primitive.
	// Blocks until the named projection's cursor reaches minSeq, or the
	// timeout elapses. DB-authoritative: server polls projection_state
	// every 1s with a NATS pub/sub hint for low latency. Unary caps at
	// 60s; use WaitProjectionCatchupStream for waits that may exceed
	// typical proxy idle timeouts.
	WaitProjectionCatchup(context.Context, *connect.Request[v1.WaitProjectionCatchupRequest]) (*connect.Response[v1.WaitProjectionCatchupResponse], error)
	WaitProjectionCatchupBatch(context.Context, *connect.Request[v1.WaitProjectionCatchupBatchRequest]) (*connect.Response[v1.WaitProjectionCatchupBatchResponse], error)
	WaitForEvent(context.Context, *connect.Request[v1.WaitForEventRequest]) (*connect.Response[v1.WaitProjectionCatchupResponse], error)
	// Streaming wait for catchup (issue #476) — supports long waits by
	// emitting periodic heartbeat frames to keep proxies/LBs from closing
	// the connection on idle. Server caps the wait at 300s. Progress
	// frames are sent on each cursor advance; a terminal DONE frame is
	// sent on catch-up, timeout, or error, after which the stream closes.
	WaitProjectionCatchupStream(context.Context, *connect.Request[v1.WaitProjectionCatchupRequest], *connect.ServerStream[v1.WaitProjectionCatchupStreamResponse]) error
}

